using LegendaryExplorerCore.Helpers;
using LegendaryExplorerCore.Misc;
using LegendaryExplorerCore.Packages;
using LegendaryExplorerCore.Unreal;
using LegendaryExplorerCore.Unreal.BinaryConverters;
using LegendaryExplorerCore.Unreal.Collections;
using ProjectMilanCore;

namespace ProjectMilan.Pipelines.Mod.BaseDelta
{
    /// <summary>
    /// Patches the basegame GuidCache.pcc. It starts from the precomputed GuidCache checked in under
    /// Mod/PrecomputedBASEGAME (generated by Conformance.BuildGuidMap), then adds the packages the other
    /// BaseDelta targets introduced or re-guided (see <see cref="InventoryPackages"/>), so a package a
    /// patch adds to SFXGame is known to clients and the server the same way a vanilla one is.
    /// </summary>
    internal class GuidCachePatchTarget : IBasePatchClass
    {
        private const string LOG_CATEGORY = "Milan-GuidCache";

        public string GameFile => "GuidCache.pcc";

        public string Comment => "Basegame GuidCache with Milan package guids";

        public byte[] GetVanillaBytes()
        {
            // Same state as the patched bytes (see ScriptPackagePatchTarget.GetVanillaBytes).
            using var vanillaPackage = MEPackageHandler.OpenMEPackage(BaseDeltaHandler.GetVanillaCookedFilePath(GameFile));
            return vanillaPackage.SaveToStream(BaseDeltaHandler.UseCompressedPackages).ToArray();
        }

        /// <summary>
        /// Must run after every other target has recorded its delta, as that is what fills
        /// <see cref="BaseDeltaHandler.GuidCacheAdditions"/>.
        /// </summary>
        public byte[] BuildPatchTarget()
        {
            var precomputed = Path.Combine(MilanShared.PipelineRoot, @"Mod", @"PrecomputedBASEGAME", GameFile);
            if (!File.Exists(precomputed))
            {
                throw new FileNotFoundException($"Precomputed basegame package not found: {precomputed}");
            }

            using var package = MEPackageHandler.OpenMEPackage(precomputed);
            var export = package.Exports[0];
            var cache = ObjectBinary.From<GuidCache>(export);

            // NameReference's hash and equality disagree on case, so don't trust hashed lookups on the map itself.
            var merged = new List<KeyValuePair<NameReference, Guid>>(cache.PackageGuidMap);
            var indexByName = new CaseInsensitiveDictionary<int>();
            for (int i = 0; i < merged.Count; i++)
            {
                indexByName.TryAdd(merged[i].Key.Instanced, i);
            }

            foreach (var (name, guid) in BaseDeltaHandler.GuidCacheAdditions)
            {
                if (indexByName.TryGetValue(name, out var index))
                {
                    if (merged[index].Value == guid)
                        continue;

                    MilanLog.Information($"Updating guid of {name}: {merged[index].Value} -> {guid}", customPrefix: LOG_CATEGORY);
                    merged[index] = new KeyValuePair<NameReference, Guid>(merged[index].Key, guid);
                }
                else
                {
                    MilanLog.Information($"Adding {name} ({guid})", customPrefix: LOG_CATEGORY);
                    indexByName[name] = merged.Count;
                    merged.Add(new KeyValuePair<NameReference, Guid>(NameReference.FromInstancedString(name), guid));
                }
            }

            var map = new UMultiMap<NameReference, Guid>();
            foreach (var (name, guid) in merged)
            {
                map.TryAddUnique(name, guid);
            }
            cache.PackageGuidMap = map;
            export.WriteBinary(cache);

            return package.SaveToStream(BaseDeltaHandler.UseCompressedPackages).ToArray();
        }

        /// <summary>
        /// Finds the root packages a patched basegame package gained or re-guided relative to vanilla, and
        /// records their guids in <paramref name="additions"/>. Same rules Conformance uses for mod packages:
        /// only root forced-export packages are cached, and only if they contain something (a stand-in for
        /// Conformance's "has net objects"). A package that needs caching but has no guid is fatal: the
        /// patched package would disagree with the cache.
        /// </summary>
        internal static void InventoryPackages(string gameFile, byte[] vanilla, byte[] patched, IDictionary<string, Guid> additions)
        {
            using var vanillaPackage = MEPackageHandler.OpenMEPackageFromStream(new MemoryStream(vanilla), gameFile);
            using var patchedPackage = MEPackageHandler.OpenMEPackageFromStream(new MemoryStream(patched), gameFile);

            var vanillaGuids = new CaseInsensitiveDictionary<Guid>();
            foreach (var exp in vanillaPackage.Exports.Where(IsRootPackage))
            {
                vanillaGuids.TryAdd(exp.ObjectName.Instanced, exp.PackageGUID);
            }

            foreach (var exp in patchedPackage.Exports.Where(IsRootPackage))
            {
                var name = exp.ObjectName.Instanced;
                var isNew = !vanillaGuids.TryGetValue(name, out var vanillaGuid);
                if (!isNew && vanillaGuid == exp.PackageGUID)
                    continue;

                if (!patchedPackage.Exports.Any(x => IsDescendantOf(x, exp)))
                {
                    MilanLog.Information($"{gameFile}: not guid caching {name}, it has no objects", customPrefix: LOG_CATEGORY);
                    continue;
                }

                if (exp.PackageGUID == Guid.Empty)
                {
                    MilanLog.Fatal($"{gameFile} {(isNew ? "adds" : "changes")} package {name} but it has no package guid, so it can't go in the GuidCache - this is a fatal error.", customPrefix: LOG_CATEGORY);
                    Environment.Exit(1);
                }

                MilanLog.Information($"{gameFile}: {(isNew ? "new" : "re-guided")} package {name} will be added to the GuidCache", customPrefix: LOG_CATEGORY);
                additions[name] = exp.PackageGUID;
            }
        }

        private static bool IsRootPackage(ExportEntry exp) => exp.idxLink == 0 && exp.ClassName == "Package" && exp.IsForcedExport;

        private static bool IsDescendantOf(IEntry entry, IEntry ancestor)
        {
            for (var parent = entry.Parent; parent != null; parent = parent.Parent)
            {
                if (parent == ancestor)
                    return true;
            }
            return false;
        }
    }
}
